return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Greek','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:26+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'el','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" αποθηκεύτηκε.','"%1$s" created. %2$d template updated.'=>'"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.' . "\0" . '"%1$s" δημιουργήθηκε. %2$d πρότυπα ενημερώθηκαν.','"%s" created.'=>'"%s" δημιουργήθηκε.','%d language not yet linked'=>'%d γλώσσα δεν έχει ακόμη συσχετιστεί' . "\0" . '%d γλώσσες δεν έχουν ακόμη συσχετιστεί','%d link updated.'=>'%d σύνδεσμος ενημερώθηκε.' . "\0" . '%d σύνδεσμοι ενημερώθηκαν.','%d locale pack installed.'=>'%d πακέτο locale εγκατεστημένο.' . "\0" . '%d πακέτα locale εγκατεστημένα.','%d navigation reference updated.'=>'Ενημερώθηκε %d αναφορά πλοήγησης.' . "\0" . 'Ενημερώθηκαν %d αναφορές πλοήγησης.','%d part reference updated.'=>'Ενημερώθηκε %d αναφορά τμήματος.' . "\0" . 'Ενημερώθηκαν %d αναφορές τμήματος.','%s Archive'=>'%s Αρχείο','(avg %.1f hits/block)'=>'(μέσος όρος %.1f επιτυχίες/μπλοκ)','(avg %.1f hits/entry)'=>'(μέσο όρο %.1f χτυπήματα/καταχώριση)','(disabled)'=>'(απενεργοποιημένο)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} δεν είχαν αντικαταστάσιους συνδέσμους — επανεξέταση για διερεύνηση)','.txt file(s) in the directory'=>'.txt αρχεία στον κατάλογο','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d τοπικοποιημένο(α) πρότυπο(α) από το θέμα &#8220;%2$s&#8221;» διατηρούνται στη βάση δεδομένων, αλλά είναι επί του παρόντος ανενεργά. Θα ενεργοποιηθούν ξανά αν ενεργοποιήσετε ξανά αυτό το θέμα. Για να μεταφέρετε τις μεταφράσεις σας στο νέο θέμα, αναγεννήστε τες μέσω <strong>Ρυθμίσεις → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> αυτόματοι διορθώσιμοι σύνδεσμοι','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> σύνδεσμοι που χρειάζονται χειροκίνητο έλεγχο','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> παρωχημένη διαδρομή(ες)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> πρόβλημα(τα) προτύπου','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Δέχεται μόνο συμπιεσμένα αρχεία .mo. Το όνομα αρχείου πρέπει να ακολουθεί το μοτίβο {textdomain}-{locale}.mo. Η μεταφόρτωση αρχείου με το ίδιο όνομα με υπάρχον θα το αντικαταστήσει.','Action'=>'Ενέργεια','Actions'=>'Ενέργειες','active'=>'ενεργό','Active Languages'=>'Ενεργές Γλώσσες','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Ενεργές γλώσσες: προσθέστε κάθε γλώσσα που θέλετε να υποστηρίξετε. Κάθε γλώσσα λαμβάνει ένα πρόθεμα URL ή υποτομέα και μια ετικέτα hreflang στην ενότητα &lt;head&gt; της σελίδας.','Active Provider'=>'Ενεργός Πάροχος','Add entry'=>'Προσθήκη καταχώρισης','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Προσθέστε οδηγίες για βελτίωση του προσχεδίου — π.χ. κάντε το πιο σύντομο, προσθέστε μια ενότητα συμπερασμάτων, χρησιμοποιήστε πιο επίσημο ύφος, συμπεριλάβετε ένα μπλοκ FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Προσθέστε οδηγίες για βελτίωση του προσχεδίου — π.χ. κάντε το πιο σύντομο, προσθέστε μια ενότητα συμπερασμάτων, χρησιμοποιήστε πιο επίσημο ύφος…','Add new entry'=>'Προσθήκη νέας καταχώρισης','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Προσθέστε έναν όρο ανά γραμμή. Απαιτούνται τόσο ο πηγή όσο και η μεταφρασμένη έκδοση. Το ζεύγος γλωσσών καθορίζει σε ποιες εργασίες μετάφρασης εφαρμόζεται ο περιορισμός.','Adds a link to the home page so visitors can browse in their language.'=>'Προσθέτει έναν σύνδεσμο στη σελίδα αρχικής ώστε οι επισκέπτες να μπορούν να περιηγούνται στη γλώσσα τους.','Administrators only (manage_options)'=>'Μόνο διαχειριστές (διαχείριση_επιλογών)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Μετά την αλλαγή της κύριας γλώσσας, εκκαθαρίστε τους permalinks (ενότητα παρακάτω) για να ενημερωθεί η δρομολόγηση URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Μετά την αλλαγή των ρυθμίσεων δομής URL (πρόθεμα διαδρομής ↔ υποτομέας), επισκεφθείτε πάντα τις Ρυθμίσεις → Μόνιμοι σύνδεσμοι και κάντε κλικ στην Αποθήκευση αλλαγών για να εκκαθαρίσετε τους κανόνες ανακατεύθυνσης.','AI Behaviour Preset'=>'Προκαθορισμένο AI Συμπεριφοράς','AI cache cleared. %d entry was removed.'=>'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχώριση αφαιρέθηκε.' . "\0" . 'Η προσωρινή μνήμη ΤΝ διαγράφηκε. %d καταχωρίσεις αφαιρέθηκαν.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Cache: λίστα αποθηκευμένων απαντήσεων AI με αριθμούς χτυπημάτων. Εκκαθαρίστε ολόκληρη την cache ή τις καταχωρίσεις μιας ανάρτησης. Χρησιμοποιήστε το "Εκκαθάριση" πριν δοκιμάσετε μια αλλαγή μετάφρασης — τα αποθηκευμένα αποτελέσματα επιστρέφονται ακόμη και όταν αλλάζετε την προεπιλογή ή το μοντέλο AI μέχρι να εκδιωχθεί η καταχώριση της cache.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Οι λειτουργίες AI είναι προαιρετικές. Η δρομολόγηση γλωσσών, το hreflang, ο διακόπτης γλώσσας και το σύστημα ομάδας μετάφρασης λειτουργούν όλα χωρίς διαμορφωμένο πάροχο.','AI Limits & Security'=>'Όρια AI & Ασφάλεια','AI provider returned an empty response.'=>'Ο πάροχος AI επέστρεψε κενή απάντηση.','AI Usage'=>'Χρήση AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Στόχος 120–160 χαρακτήρες. Αφήστε κενό για χρήση της εναλλακτικής λύσης από το απόσπασμα.','All time'=>'Όλο το χρόνο','Allow editors to lock individual blocks'=>'Επιτρέψτε στους επιμελητές να κλειδώνουν μεμονωμένα μπλοκ','Allow Gutenberg template-editing mode on post screens'=>'Επιτρέψτε τη λειτουργία επεξεργασίας προτύπων Gutenberg στις οθόνες δημοσιεύσεων','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Επίσης διαγραφή αναθέσεων γλωσσών, σχέσεων μετάφρασης, μετα-περιγραφών, γλωσσάριου και μνήμης μετάφρασης όταν το πρόσθετο απεγκαθίσταται','Also generate meta description'=>'Επίσης δημιουργήστε μετα-περιγραφή','Alternative (server-side):'=>'Εναλλακτικά (διακομιστής-πλευρά):','An unknown error occurred.'=>'Παρουσιάστηκε άγνωστο σφάλμα.','and'=>'και','Anthropic (Claude)'=>'Ανθρώπινη (Κλαούντ)','any'=>'οποιαδήποτε','API calls saved by cache'=>'Κλήσεις API αποθηκευμένες από την cache','API Key'=>'Κλειδί API','API Keys'=>'Κλειδιά API','API Keys Tab'=>'Επικεφαλίδα API Keys','API Response Cache'=>'Cache Απαντήσεων API','Applied ✓'=>'Εφαρμόστηκε ✓','Apply failed — please try again.'=>'Η εφαρμογή απέτυχε — παρακαλώ δοκιμάστε ξανά.','Apply to Block'=>'Εφαρμογή στο μπλοκ','Apply to Editor'=>'Εφαρμογή στον Επεξεργαστή','Apply to Footnote'=>'Εφαρμογή στην υποσημείωση','Apply to Meta Description'=>'Εφαρμογή στη Μετα-περιγραφή','Apply translation'=>'Εφαρμογή μετάφρασης','Applying…'=>'Εφαρμόζεται…','Approximate size'=>'Περίπου μέγεθος','Archive'=>'Αρχείο','Archive: %s'=>'Αρχείο: %s','Authors and above (edit_published_posts)'=>'Συγγραφείς και άνω (επεξεργασία_δημοσιευμένων_αναρτήσεων)','Behavior'=>'Συμπεριφορά','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Συμπεριφορά: επιλέξτε την προεπιλογή AI (Literal, Balanced, Creative), προσθέστε καθολικές οδηγίες προτροπής, ενεργοποιήστε ή απενεργοποιήστε την αυτόματη μετάφραση μετά την αποθήκευση ανάρτησης και διαμορφώστε τη Μνήμη Μετάφρασης.','Block Content'=>'Περιεχόμενο μπλοκ','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Παρουσιάζει μια ευγενική ειδοποίηση όταν η τρέχουσα σελίδα εμφανίζεται στη γλώσσα πηγής της επειδή δεν υπάρχει μετάφραση για τη γλώσσα του επισκέπτη. Τροφοδοτείται από το σήμα LINGUAFORGE_LANG_FALLBACK_ACTIVE του δρομολογητή Lingua Forge — δεν εκπέμπει τίποτα όταν υπάρχει μετάφραση για τη ζητούμενη τοποθεσία.','Block Editor'=>'Επεξεργαστής Μπλοκ','block keywordfallback'=>'εναλλακτική','block keywordi18n'=>'i18n','block keywordlanguage'=>'γλώσσα','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'μετάφραση','Block locking'=>'Κλείδωμα μπλοκ','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Μοτίβα μπλοκ που έχουν καταχωρηθεί για προσαρμοσμένους τύπους ανάρτησης. Χρησιμοποιήστε το κουμπί Μετάφραση για να δημιουργήσετε μια παραλλαγή γλώσσας. Το μεταφρασμένο περιεχόμενο αποθηκεύεται εδώ και μπορεί να αντιγραφεί σε οποιαδήποτε ανάρτηση CPT από τον εισαγωγέα μοτίβων επεξεργαστή μπλοκ ή να χρησιμοποιηθεί ως σημείο εκκίνησης για ένα Συγχρονισμένο Μοτίβο (Επαναχρησιμοποιήσιμο Μπλοκ).','block titleMissing Translation Notice'=>'Ειδοποίηση απουσίας μετάφρασης','Block translation reuses'=>'Χρήση επαναχρησιμοποίησης μετάφρασης μπλοκ','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Μνήμη cache μετάφρασης επιπέδου μπλοκ που μοιράζεται μεταξύ αναρτήσεων. Όταν ενεργοποιείται, τα ίδια μπλοκ (ίδια μορφοποίηση, ζεύγος γλωσσών και γλωσσάρι) σερβίρονται από τη μνήμη αντί να καλούν ξανά το AI. Διαμορφώστε στις Ρυθμίσεις → Συμπεριφορά.','Browser language redirect'=>'Ανακατεύθυνση γλώσσας περιηγητή','Built-in preset instructions:'=>'Ενσωματωμένες προεπιλεγμένες οδηγίες:','Bulletize (•-prefixed)'=>'Καταγράψτε με κουκκίδες (•-προσημειωμένο)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Αποθηκεύει μεταφραστικά ισοδύναμα σε επίπεδο μπλοκ ώστε το επαναχρησιμοποιήσιμο περιεχόμενο (κοινά υποσέλιδα, πλαϊνές γραμμές, ακορντεόν, νομικές ενότητες με πολύ κείμενο) να μην κάνει κλήση API κάθε φορά. Όταν ενεργοποιείται, η ροή μετάφρασης αναλύει κάθε δημοσίευμα σε μπλοκ, ελέγχει κάθε μπλοκ στη μνήμη cache και στέλνει μόνο τα μη αποθηκευμένα μπλοκ στο AI σε μια ενιαία αίτηση. Οι επεξεργασίες γλωσσάρι και οι αλλαγές στην προεπιλογή Συμμόρφωσης ακυρώνουν αυτόματα τις επηρεαζόμενες αποθηκευμένες μεταφράσεις. Προβολή στατιστικών και διαγραφή της μνήμης cache στην ενότητα Συντήρηση.','cached'=>'αποθηκευμένο','Cached API responses'=>'Αποθηκευμένες απαντήσεις API','Cached block translations'=>'Αποθηκευμένες μεταφράσεις μπλοκ','Cancel'=>'Ακύρωση','Cannot determine target language from slug.'=>'Αδύνατη η προσδιορισμός της στόχου γλώσσας από το slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Περιορίστε τη χρήση AI που μπορεί να παράγει ο ιστότοπος και περιορίστε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν πληρωμένες κλήσεις AI. Βρίσκεται πάνω από το όριο ρυθμού ανά χρήστη (30 αιτήματα / λεπτό, σκληρά κωδικοποιημένο) που ήδη προστατεύει από ανεξέλεγκτες επαναλήψεις χρήστη.','chars'=>'χαρακτήρες','Chunk translated'=>'Μπλοκ μεταφράστηκε','Chunk translated to:'=>'Μπλοκ μεταφράστηκε σε:','Clear'=>'Καθαρισμός','Clear All'=>'Καθαρισμός όλων','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Εκκαθάριση όλων των αποθηκευμένων αποτελεσμάτων ΤΝ; Οι μελλοντικά αιτήματα θα ενεργοποιούν νέες κλήσεις API μέχρι να ξαναχτιστεί η προσωρινή μνήμη.','Clear API Response Cache'=>'Εκκαθάριση Cache Απαντήσεων API','Clear Debug Files'=>'Διαγραφή αρχείων αποσφαλμάτωσης','Clear hints'=>'Καθαρισμός υποδείξεων','Clear input'=>'Καθαρισμός εισόδου','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Εκκαθάριση ολόκληρης της μνήμης μετάφρασης; Οι μελλοντικές μεταφράσεις θα ξαναχτίσουν την cache καθώς εκτελούνται.','Clear Translation Memory'=>'Εκκαθάριση μνήμης μετάφρασης','Close'=>'Κλείσιμο','Close language panel'=>'Κλείσιμο πάνελ γλώσσας','Close popover'=>'Κλείσιμο αναδυόμενου','Compliance Preset'=>'Προεπιλογή Συμμόρφωσης','Content generated'=>'Δημιουργήθηκε περιεχόμενο','Content Generator'=>'Παραγωγός Περιεχομένου','Content ready'=>'Το περιεχόμενο είναι έτοιμο','Contributors and above — default (edit_posts)'=>'Συνεισφέροντες και άνω — προεπιλογή (επεξεργασία_αναρτήσεων)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Ελέγξτε πόσο περιεχόμενο αποστέλλεται στην AI και πόσο μεγάλο μπορεί να είναι το απάντημα. Αφήστε ένα πεδίο κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειγμα). Αυξήστε αυτές τις τιμές αν μεγάλες σελίδες κόβονται, μειώστε τις για να μειώσετε το κόστος API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Ελέγχει τον προϋπολογισμό δείκτη και τα όρια εισόδου για τη λειτουργία Παραγωγέα Περιεχομένου ΤΝ. Αφήστε τα πεδία κενά για να χρησιμοποιήσετε τις ενσωματωμένες προεπιλογές.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Ελέγχει τι συμβαίνει όταν ένας διαχειριστής διαγράφει το πρόσθετο από τα Πρόσθετα → Εγκατεστημένα πρόσθετα → Διαγραφή. Οι ρυθμίσεις και οι cache AI διαγράφονται πάντα. Οι αναθέσεις γλωσσών και οι σχέσεις μετάφρασης διατηρούνται από προεπιλογή ώστε μια τυχαία απεγκατάσταση ή επανεγκατάσταση να συνεχίσει από εκεί που σταμάτησε.','Conversational'=>'Διαλογικό','Copied ✓'=>'Αντιγράφηκε ✓','Copy'=>'Αντιγραφή','Copy markup'=>'Αντιγραφή κώδικα','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Αντιγράψτε το αποτέλεσμα και επικολλήστε το όπου χρειάζεται (π.χ. απευθείας στο πεδίο σημείωσης).','Copy to safe storage'=>'Αντιγραφή σε ασφαλή αποθήκευση','Could not add entry: source term and target term are required.'=>'Αδυναμία προσθήκης καταχώρισης: απαιτούνται όρος πηγής και όρος στόχου.','Could not copy the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αντιγραφή του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Could not instantiate the provider.'=>'Δεν ήταν δυνατή η δημιουργία του παρόχου.','Could not save the file. Check that the uploads folder is writable.'=>'Δεν ήταν δυνατή η αποθήκευση του αρχείου. Ελέγξτε αν ο φάκελος ανεβάσματος είναι εγγράψιμος.','Could not save the glossary entry.'=>'Αδυναμία αποθήκευσης της καταχώρισης λεξικού.','CPT Block Patterns'=>'Μοτίβα μπλοκ CPT','Create'=>'Δημιουργία','Create missing'=>'Δημιουργία ελλείποντος','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Η δημιουργία μεταφράσεων για τον τύπο δημοσίευσης "%s" απαιτεί ενεργή ενσωμάτωση. Παρακαλώ βεβαιωθείτε ότι η απαιτούμενη ενσωμάτωση είναι εγκατεστημένη και ενεργή.','Creating…'=>'Δημιουργία…','Creative / Marketing'=>'Δημιουργικό / Μάρκετινγκ','Creative / Marketing instructions'=>'Δημιουργικές / Μάρκετινγκ οδηγίες','Current content (will be overwritten)'=>'Τρέχον περιεχόμενο (θα αντικατασταθεί)','Current title'=>'Τρέχων τίτλος','Current: {current}'=>'Τρέχον: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Αυτή τη στιγμή κληρονομείται από τη σταθερά %s. Επιλέγοντας μια τιμή εδώ θα την αντικαταστήσει.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Αυτή τη στιγμή παραλείπεται για δημοσιεύματα που χρησιμοποιούν εικονίδια θέματος μπλοκ-comment (wp:details πεδία περίληψης, κ.λπ.) — αυτά περνούν στη υπάρχουσα διαδρομή μετάφρασης με μία κλήση.','Currently:'=>'Τρέχον: ','Custom'=>'Προσαρμοσμένο','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Η ημερήσια ποσόστωση AI έχει φτάσει (%1$d αιτήματα). Επαναφέρεται στις %2$s UTC.','Daily request limit'=>'Όριο ημερήσιων αιτημάτων','Debug Files'=>'Αρχεία αποσφαλμάτωσης','Debug files cleared. %d file was removed.'=>'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχείο αφαιρέθηκε.' . "\0" . 'Τα αρχεία αποσφαλμάτωσης διαγράφηκαν. %d αρχεία αφαιρέθηκαν.','Debug logging'=>'Καταγραφή αποσφαλμάτωσης','Debug logging disabled.'=>'Η καταγραφή αποσφαλμάτωσης απενεργοποιήθηκε.','Debug logging enabled.'=>'Η καταγραφή αποσφαλμάτωσης ενεργοποιήθηκε.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Ανίχνευση σφαλμάτων: ενεργοποιήστε το αρχείο καταγραφής αποσφαλμάτωσης για να καταγράψετε τις προτροπές AI και τις απαντήσεις API σε τοπικό αρχείο. Απενεργοποιήστε μετά την αντιμετώπιση προβλημάτων — η λειτουργία αποσφαλμάτωσης γράφει ένα αρχείο σε κάθε αίτημα AI.','Delete'=>'Διαγραφή','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Διαγραφή όλων των αρχείων .txt στον κατάλογο αποσφαλμάτωσης; Ο ίδιος ο κατάλογος θα παραμείνει ώστε οι μελλοντικές εγγραφές αποσφαλμάτωσης να καταλήγουν καθαρές.','Delete all files for this override (both .mo and .po)?'=>'Διαγράψτε όλα τα αρχεία αυτής της παρακάμψεως (τόσο .mo όσο και .po);','Delete content data on uninstall'=>'Διαγραφή δεδομένων περιεχομένου κατά την απεγκατάσταση','Delete this glossary entry?'=>'Να διαγραφεί αυτή η καταχώριση λεξικού;','Describe what to write — topic, key points, structure…'=>'Περιγράψτε τι να γράψετε — θέμα, βασικά σημεία, δομή…','Directory'=>'Κατάλογος','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Απενεργοποίηση κατά τη διάρκεια ρύθμισης προτροπής ή όταν χρειάζεστε κάθε αίτημα να φτάσει στον πάροχο AI. Η απενεργοποίηση δεν διαγράφει τις αποθηκευμένες καταχωρίσεις — η επανενεργοποίησή τους τις επαναφέρει. Η άμεση αύξηση της δαπάνης API σε απασχολημένους ιστότοπους αναμένεται όταν είναι απενεργοποιημένο.','Display'=>'Εμφάνιση','Displays the Lingua Forge language switcher.'=>'Εμφανίζει τον διακόπτη γλώσσας Lingua Forge.','Documentation'=>'Τεκμηρίωση','Done'=>'Ολοκληρώθηκε','Done — {done} of {total} post(s) fixed.'=>'Ολοκληρώθηκε — διορθώθηκαν {done} από {total} αναρτήσεις.','Down'=>'Κάτω','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Κατεβάστε και εγκαταστήστε ένα πακέτο γλώσσας πυρήνα WordPress απευθείας από το WordPress.org. Μόλις εγκατασταθεί, η locale γίνεται διαθέσιμη για δρομολόγηση URL και τη ροή εργασίας μετάφρασης AI. Η λίστα των διαθέσιμων γλωσσών λαμβάνεται κατ\' απαίτηση — κάντε κλικ στο κουμπί παρακάτω για φόρτωση.','Dropdown direction'=>'Κατεύθυνση αναδυόμενου μενού','Editors and above (edit_others_posts)'=>'Επεξεργαστές και άνω (επεξεργασία_άλλων_αναρτήσεων)','Enable API response caching'=>'Ενεργοποίηση cache απαντήσεων API','Enable block-level translation cache reuse across posts'=>'Ενεργοποίηση επανάχρησης cache μεταφράσεων σε επίπεδο μπλοκ σε δημοσιεύματα','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Εισάγετε το κλειδί API για τουλάχιστον έναν πάροχο AI. Τα κλειδιά είναι κρυπτογραφημένα σε κατάσταση αναμονής χρησιμοποιώντας AES-256-GCM με ένα μυστικό συγκεκριμένο για τον ιστότοπο (LINGUAFORGE_SECRET). Μην μοιράζεστε εξαγωγές βάσεων δεδομένων χωρίς πρώτα να περιστρέψετε το μυστικό.','environment variable'=>'μεταβλητή περιβάλλοντος','Error'=>'Σφάλμα','Expand'=>'Επεκτείνετε','Expected: {expected}'=>'Αναμενόμενο: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Επιπλέον καθοδήγηση — τόνος, στυλ, περιορισμοί, κοινό-στόχος…','Extra guidance — tone, style, constraints…'=>'Επιπλέον καθοδήγηση — τόνος, στυλ, περιορισμοί…','Failed. Please try again.'=>'Απέτυχε. Παρακαλώ δοκιμάστε ξανά.','Feature'=>'Λειτουργία','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Οι λειτουργίες ομαδοποιούνται σε δύο επίπεδα. Εισάγετε τον ακριβή αναγνωριστικό μοντέλου για κάθε επίπεδο και πάροχο. Αφήστε κενό ένα πεδίο για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή (εμφανίζεται ως υπόδειξη). Μόνο τα μοντέλα του ενεργού παρόχου καλούνται κατά την εκτέλεση — διαμορφώστε τα άλλα εκ των προτέρων αν σκοπεύετε να αλλάξετε.','File copied to safe storage successfully.'=>'Το αρχείο αντιγράφηκε με επιτυχία σε ασφαλή αποθήκευση.','Files'=>'Αρχεία','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Τα αρχεία καταλήγουν στον παρακάτω κατάλογο. Χρησιμοποιείται για διάγνωση θεμάτων μετάφρασης — απενεργοποιήστε μόλις έχετε ό,τι χρειάζεστε ώστε τα αρχεία να μην συσσωρεύονται. Μπορείτε επίσης να το επιβάλετε από το wp-config.php με `define( \'LINGUAFORGE_AI_DEBUG\', true );` που υπερισχύει αυτής της εναλλαγής.','Filter'=>'Φίλτρο','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Φίλτρο με το linguaforge_debug_dir για ανακατεύθυνση της εξόδου αποσφαλμάτωσης σε μη δημόσιο προορισμό.','Fix'=>'Διόρθωση','Fix All'=>'Διόρθωσε Όλα','Fix all links'=>'Επιδιόρθωση όλων των συνδέσμων','Fix all parts'=>'Επιδιόρθωση όλων των μερών','Fix Links'=>'Επιδιόρθωση Συνδέσμων','Fix Nav'=>'Επιδιόρθωση Πλοήγησης','Fix Parts'=>'Επιδιόρθωση Μερών','Fix Template'=>'Διόρθωση Προτύπου','Fixing {n} / {total}…'=>'Διόρθωση {n} / {total}…','Fixing…'=>'Επιδιόρθωση…','Flush Permalink Rules'=>'Καθαρισμός Κανόνων Permalink','Flush Permalinks'=>'Καθαρισμός Permalinks','Footnote Content'=>'Περιεχόμενο υποσημείωσης','footnote(s) translated — applied together with content.'=>'Μεταφρασμένες σημειώσεις (footnote) — εφαρμόζονται μαζί με το περιεχόμενο.','Footnotes'=>'Σημειώσεις','Footnotes payload (advanced)'=>'Περιεχόμενο υποσημειώσεων (προχωρημένο)','Forbidden'=>'Απαγορεύεται','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΑΠΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Επιβολή ΕΝΕΡΓΟ από το σταθερό LINGUAFORGE_AI_DEBUG στο wp-config.php. Αφαιρέστε αυτήν τη γραμμή για να ελέγξετε αυτήν την εναλλαγή από εδώ.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Βρέθηκαν {parts} σε <strong>{total}</strong> από <strong>{scanned}</strong> ανιχνευμένες αναρτήσεις για <strong>{lang}</strong>.','From'=>'Από','Front Page'=>'Αρχική Σελίδα','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Τοπική διαμόρφωση FSE: σκαλωσιά, μετάφραση και διόρθωση συνδέσμων σε πρότυπα και τμήματα προτύπων του Full Site Editing απευθείας από αυτήν την καρτέλα.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Τα πρότυπα FSE που έχουν δημιουργηθεί από το ενεργό θέμα. Δημιουργήστε και προσαρμόστε στο Επεξεργαστή Ιστοσελίδας.','Full Article'=>'Ολόκληρο το άρθρο','Full post'=>'Πλήρες ποστ','General'=>'Γενικά','Generate'=>'Δημιουργία','Generate Content'=>'Παραγωγή περιεχομένου','Generate content…'=>'Δημιουργία περιεχομένου…','Generate Excerpt'=>'Δημιουργία αποσπάσματος','Generate Meta Description'=>'Δημιουργία μετα-περιγραφής','Generated Content'=>'Παραγόμενο Περιεχόμενο','Generated meta description'=>'Παραγόμενη μετα-περιγραφή','Generating…'=>'Παραγωγή…','Generation failed.'=>'Η δημιουργία απέτυχε.','Getting started'=>'Εκκίνηση','Global AI preset'=>'Παγκόσμια προεπιλογή AI','Global default (%s)'=>'Παγκόσμια προεπιλογή (%s)','Glossary'=>'Γλωσσάρι','Glossary entry added.'=>'Καταχώριση λεξικού προστέθηκε.','Glossary entry removed.'=>'Καταχώριση λεξικού αφαιρέθηκε.','Glossary Tab'=>'Γλωσσάρι','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Απόκρυψη','Hints'=>'Υποδείξεις','Home link text'=>'Κείμενο συνδέσμου αρχικής','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Πώς πρέπει να εμφανίζεται στη μετάφραση. Πληκτρολογήστε την ίδια τιμή με τον όρο πηγής για να την διατηρήσετε αυτούσια.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Εικονίδιο + ετικέτα','Icon only'=>'Μόνο εικονίδιο','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Εάν επιλεγεί, η απεγκατάσταση του πρόσθετου θα διαγράψει οριστικά όλες τις αναθέσεις γλωσσών, σχέσεις μετάφρασης, μετα-περιγραφές, προεπιλογές σελίδων, το γλωσσάρι AI και τη μνήμη μετάφρασης για κάθε ανάρτηση σε αυτόν τον ιστότοπο. Αυτό δεν μπορεί να αναιρεθεί. Αφήστε το ανεπιλεγμένο εκτός αν αφαιρείτε πλήρως την πολύγλωσση υποστήριξη από τον ιστότοπο.','Improve writing'=>'Βελτίωση γραφής','Informative'=>'Ενημερωτικό','Input tokens'=>'Εισαγωγικά tokens','Install'=>'Εγκατάσταση','Install a Language'=>'Εγκατάσταση Γλώσσας','Installing…'=>'Εγκατάσταση…','Instructions (optional)'=>'Οδηγίες (προαιρετικά)','Instructions / key points'=>'Οδηγίες / βασικά σημεία','Integration API'=>'API Ενσωμάτωσης','Internal Link Fixer'=>'Εργαλείο Διόρθωσης Εσωτερικών Συνδέσμων','Introduction only'=>'Μόνο εισαγωγή','Invalid file reference.'=>'Μη έγκυρη αναφορά αρχείου.','Invalid filename.'=>'Μη έγκυρο όνομα αρχείου.','Invalid language.'=>'Μη έγκυρη γλώσσα.','Invalid locale code.'=>'Μη έγκυρος κωδικός locale.','Invalid or primary language.'=>'Μη έγκυρη ή κύρια γλώσσα.','Invalid post type.'=>'Μη έγκυρος τύπος ανάρτησης.','Invalid template part.'=>'Μη έγκυρο τμήμα προτύπου.','Invalid template type.'=>'Μη έγκυρος τύπος προτύπου.','Key points, ideas, or structure to build from…'=>'Βασικά σημεία, ιδέες ή δομή από την οποία να χτιστεί…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Τα κλειδιά είναι κρυπτογραφημένα με AES-256-CBC πριν αποθηκευτούν στη βάση δεδομένων του WordPress. Το μυστικό κρυπτογράφησης προέρχεται από τα salts αυθεντικοποίησης του WordPress (wp-config.php), έτσι τα κείμενα σε απλό κείμενο ποτέ δεν έρχονται σε επαφή με τη βάση δεδομένων.','Language'=>'Γλώσσα','Language %s installed successfully.'=>'Η γλώσσα %s εγκαταστάθηκε με επιτυχία.','Language (optional)'=>'Γλώσσα (προαιρετικά)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή (ορίζεται το DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Η εγκατάσταση γλώσσας είναι απενεργοποιημένη σε αυτόν τον διακομιστή. Η σταθερά DISALLOW_FILE_MODS ορίζεται στο wp-config.php. Εγκαταστήστε χειροκίνητα πακέτα γλώσσας μέσω WP-CLI: wp language core install de_DE','Language label'=>'Ετικέτα γλώσσας','Language Overrides'=>'Παρακάμψεις Γλώσσας','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Παρεμβολές γλώσσας: διαχειριστείτε αρχεία υπεροχής .po/.mo για τις συμβολοσειρές UI του Lingua Forge. Χρησιμοποιήστε αυτό αντί να επεξεργάζεστε απευθείας αρχεία πρόσθετου — οι υπεροχές παραμένουν μετά τις ενημερώσεις.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Η εγκατάσταση πακέτου γλώσσας απέτυχε. Η γλώσσα μπορεί ήδη να είναι εγκατεστημένη, ο κωδικός locale μπορεί να είναι λανθασμένος ή ο διακομιστής σας να εμποδίζει την εγγραφή αρχείων.','Language Setup'=>'Ρύθμιση Γλώσσας','Language Switcher'=>'Εναλλαγή Γλώσσας','Language switcher'=>'Διακόπτης γλώσσας','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Αντίγραφα συγκεκριμένων γλωσσών των μερών προτύπων του θέματος. Μόλις δημιουργηθούν, τα πρότυπα ενημερώνονται ώστε να αναφέρονται στο μέρος που είναι συγκεκριμένο για τη γλώσσα.','Language:'=>'Γλώσσα:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Οι γλώσσες που είναι γνωστές στον δρομολογητή (προερχόμενες από τα εγκατεστημένα πακέτα locale του WordPress συν την κύρια γλώσσα). Εγκαταστήστε πρόσθετα πακέτα γλώσσας στην παρακάτω ενότητα για να κάνετε περισσότερες γλώσσες διαθέσιμες για δρομολόγηση και μετάφραση.','Last 30 days'=>'Τελευταία 30 ημέρες','Last 7 days'=>'Τελευταία 7 ημέρες','Lead paragraph (≤60 w)'=>'Εισαγωγική παράγραφος (≤60 λέξεις)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Αφήστε ένα πεδίο μοντέλου κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή για αυτό το επίπεδο. Το κείμενο υπόδειξης δείχνει ποιο μοντέλο θα χρησιμοποιηθεί.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Αφήστε κενό για ονόματα εμπορικών σημάτων και όρους που δεν σχετίζονται με γλώσσα και πρέπει να επιβάλλονται ανεξάρτητα από τη γλώσσα μεταφράσης.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Αφήστε κενό για να εφαρμοστεί σε όλες τις στοχευόμενες γλώσσες — ιδανικό για ονόματα εμπορικών σημάτων, συντομογραφίες και όρους που πρέπει να διατηρούνται αυτούσιοι σε κάθε μετάφραση.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Αφήστε κενό για να διατηρήσετε το υπάρχον κλειδί. Εισάγετε μια νέα τιμή για να το αντικαταστήσετε.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Αφήστε κενό για να χρησιμοποιήσετε την ενσωματωμένη προεπιλογή. Η διαγραφή μιας αποθηκευμένης υπεροχής επαναφέρει την προεπιλογή στην επόμενη αποθήκευση.','Legal / Compliance'=>'Νομικό / Συμμόρφωση','Legal / Compliance instructions'=>'Νομικές / Συμμόρφωση οδηγίες','Light'=>'Ελαφρύ','Light (default — fast and cost-effective)'=>'Ελαφρύ (προεπιλογή — γρήγορο και οικονομικό)','Light (fast and cost-effective — Haiku / Flash)'=>'Ελαφρύ (γρήγορο και οικονομικό — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Φωτεινό: χρησιμοποιείται για μετα-περιγραφές και δημιουργία αποσπασμάτων — γρήγορο, χαμηλό κόστος.','Limit results to pages in the given Lingua Forge language code.'=>'Περιορίστε τα αποτελέσματα σε σελίδες με τον κωδικό γλώσσας Lingua Forge που δίνεται.','Limits'=>'Όρια','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Το Lingua Forge προσθέτει πολύγλωσση δρομολόγηση, μετάφραση με AI, ετικέτες SEO hreflang και διακόπτη γλώσσας στον ιστότοπό σας WordPress.','Lingua Forge AI Tools'=>'Εργαλεία Τεχνητής Νοημοσύνης Lingua Forge','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Το Lingua Forge περιορίζει δύο λειτουργίες του Gutenberg από προεπιλογή για να διατηρεί συνεπή τη συμπεριφορά της επιμέλειας σε όλες τις γλώσσες. Επιλέξτε εδώ όταν χρειάζεστε πλήρεις δυνατότητες Gutenberg / FSE.','Lingua Forge Settings'=>'Ρυθμίσεις Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Το Lingua Forge χρησιμοποιεί δύο ανεξάρτητα επίπεδα cache για να αποφύγει περιττές κλήσεις API AI. Χρησιμοποιήστε τις καρτέλες παρακάτω για να επιθεωρήσετε και να διαχειριστείτε κάθε ένα.','Lingua Forge uses two model tiers per provider:'=>'Το Lingua Forge χρησιμοποιεί δύο επίπεδα μοντέλων ανά πάροχο:','Lingua Forge — Quick Translate'=>'Lingua Forge — Γρήγορη Μετάφραση','Lingua Forge — Settings'=>'Lingua Forge — Ρυθμίσεις','link(s)'=>'σύνδεσμος(οι)','Links'=>'Σύνδεσμοι','Load available languages'=>'Φόρτωση διαθέσιμων γλωσσών','Loading…'=>'Φόρτωση…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Το Loco Translate αποθηκεύει τις προσαρμοσμένες μεταφράσεις του στον φάκελο wp-content/languages/loco/ — μια τοποθεσία που μπορεί να διαγραφεί σιωπηλά με ενημέρωση πυρήνα WP, επανεγκατάσταση πρόσθετου ή αν το Loco Translate αφαιρεθεί. Η αντιγραφή αρχείων εδώ τα μεταφέρει στον κατάλογο Lingua Forge i18n-overrides, ο οποίος διατηρείται μέσω όλων αυτών των γεγονότων και φορτώνεται αυτόματα σε κάθε αίτημα.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Αντιγραφή σε Ασφαλή Αποθήκευση','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Η χαμηλότερη δυνατότητα WordPress που επιτρέπεται να ενεργοποιήσει λειτουργίες AI. Η αυστηροποίηση αυτού σε ιστότοπους με πολλούς συγγραφείς αποτρέπει τους Συμβάλλοντες ή δοκιμαστικούς λογαριασμούς από την εκτέλεση πληρωμένων κλήσεων AI. Παρακάμπτεται ανά λειτουργία μέσω του φίλτρου linguaforge_required_capability.','Maintenance'=>'Συντήρηση','Maintenance Tab'=>'Καρτέλα Συντήρησης','Make casual'=>'Κάντε το ανεπίσημο','Make concise'=>'Κάντε το συνοπτικό','Make formal'=>'Κάντε το επίσημο','Mark citations needed'=>'Σημειώστε ότι χρειάζονται παραπομπές','Max context characters'=>'Μέγιστοι χαρακτήρες συμφραζομένων','Max hints characters'=>'Μέγιστοι χαρακτήρες υποδείξεων','Max input characters'=>'Μέγιστοι χαρακτήρες εισόδου','Max output tokens'=>'Μέγιστοι tokens εξόδου','Maximum characters accepted from the input field. Default: 8 000.'=>'Μέγιστοι χαρακτήρες που γίνονται αποδεκτοί από το πεδίο εισόδου. Προεπιλογή: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Μέγιστοι χαρακτήρες υπάρχοντος περιεχομένου ανάρτησης που περνιέται στην ΤΝ ως σπόρος συμφραζομένων όταν δεν παρέχονται Υποδείξεις. Προεπιλογή: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Μέγιστοι χαρακτήρες που διαβάζονται από το πεδίο Υποδείξεων. Προεπιλογή: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Μέγιστος αριθμός χαρακτήρων του περιεχομένου της ανάρτησης που προωθείται στην ΤΝ. 0 σημαίνει χωρίς όριο — το πλήρες περιεχόμενο αποστέλλεται πάντα (συνιστάται). Ορίστε μια μη μηδενική τιμή μόνο αν ο πάροχός σας έχει στενό πλαίσιο συμφραζομένων. Μια προειδοποίηση γράφεται στο αρχείο καταγραφής σφαλμάτων PHP κάθε φορά που το περιεχόμενο περικόπτεται.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Μέγιστος αριθμός tokens που μπορεί να παράγει η AI σε μια απάντηση μετάφρασης. Αν μια μετάφραση κόβεται σιωπηλά στο τέλος, αυξήστε αυτήν την τιμή. Προεπιλογή: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά εκτέλεση δημιουργίας. Αυξήστε το αν τα πλήρη άρθρα κόβονται. Προεπιλογή: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Μέγιστοι δείκτες που μπορεί να παράγει η ΤΝ ανά γρήγορη μετάφραση. Προεπιλογή: 2.000.','Meta Description'=>'Μετα-περιγραφή','Meta Description, Excerpt Generator'=>'Μετα-περιγραφή, Δημιουργός περίληψης','Minimum role'=>'Ελάχιστος ρόλος','Missing pattern name or language.'=>'Λείπει όνομα μοτίβου ή γλώσσα.','Mode'=>'Λειτουργία','Model'=>'Μοντέλο','Model tier'=>'Επίπεδο μοντέλου','Models'=>'Μοντέλα','Models Tab (General)'=>'Γενική καρτέλα Μοντέλων','Most recent cached block'=>'Πιο πρόσφατο αποθηκευμένο μπλοκ','Most recent cached response'=>'Πιο πρόσφατη αποθηκευμένη απάντηση','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Πολυγλωσσική δρομολόγηση, μετα-ετικέτες SEO και εργαλεία περιεχομένου AI για το WordPress. Συνδυάζει ανίχνευση γλώσσας, δρομολόγηση URL, hreflang, μετα-περιγραφές και λειτουργίες αποσπάσματος, μετα-ετικετών και μετάφρασης με τεχνητή νοημοσύνη.','Name displayed in this language. Leave empty to use the source name.'=>'Όνομα που εμφανίζεται σε αυτή τη γλώσσα. Αφήστε κενό για να χρησιμοποιήσετε το αρχικό όνομα.','Navigation'=>'Πλοήγηση','Navigation has no content to translate.'=>'Η πλοήγηση δεν έχει περιεχόμενο για μετάφραση.','Navigation not found.'=>'Δεν βρέθηκε πλοήγηση.','Navigation posts are translated via the Router tab, not this button.'=>'Οι δημοσιεύσεις πλοήγησης μεταφράζονται μέσω της καρτέλας Router, όχι με αυτό το κουμπί.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Η μετάφραση πλοήγησης απαιτεί ενεργό πάροχο AI. Διαμορφώστε ένα κλειδί API στην καρτέλα Κλειδιά API.','Navigations'=>'Πλοηγήσεις','Network error — could not reach the WordPress AJAX endpoint.'=>'Σφάλμα δικτύου — δεν ήταν δυνατή η πρόσβαση στο σημείο AJAX του WordPress.','No %s version found in this translation group.'=>'Δεν βρέθηκε έκδοση %s σε αυτήν την ομάδα μεταφράσεων.','No AI provider configured.'=>'Δεν έχει διαμορφωθεί πάροχος AI.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Δεν έχει καταγραφεί χρήση AI στο επιλεγμένο παράθυρο (%s). Επιλέξτε ευρύτερο εύρος παραπάνω.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Δεν έχει καταγραφεί ακόμη χρήση AI. Μόλις ένας επεξεργαστής εκτελέσει μια μετάφραση, δημιουργήσει μια μετα-περιγραφή ή χρησιμοποιήσει οποιαδήποτε άλλη λειτουργία AI, τα σύνολα θα εμφανιστούν εδώ.','No API key configured for this provider.'=>'Δεν έχει διαμορφωθεί κλειδί API για αυτόν τον πάροχο.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Δεν υπάρχουν ενσωματωμένες οδηγίες — κάθε λειτουργία AI χρησιμοποιεί τις δικές της ρυθμίσεις. Συμπληρώστε το πεδίο Οδηγίες προσαρμοσμένου προτροπής παρακάτω για να προσθέσετε τους δικούς σας κανόνες σε όλο τον ιστότοπο.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Δεν έχουν βρεθεί ακόμη προσαρμοσμένα αρχεία Loco Translate. Εμφανίζονται εδώ μόλις αποθηκεύσετε μια μετάφραση στο Loco Translate.','No file was selected.'=>'Δεν επιλέχθηκε αρχείο.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Δεν υπάρχουν καταχωρίσεις λεξικού που να ταιριάζουν με το τρέχον φίλτρο. Αφαιρέστε το φίλτρο για να δείτε όλες τις καταχωρίσεις ή προσθέστε μια νέα παρακάτω.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Δεν υπάρχουν ακόμα καταχωρίσεις λεξικού. Προσθέστε μία παρακάτω για να αρχίσετε να επιβάλλετε ορολογία στις μεταφράσεις.','No internal links found to update.'=>'Δεν βρέθηκαν εσωτερικοί σύνδεσμοι για ενημέρωση.','No language-specific template parts found to map.'=>'Δεν βρέθηκαν τμήματα προτύπου που να χρειάζονται χαρτογράφηση.','No navigation references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών πλοήγησης.','No override files uploaded yet.'=>'Δεν έχουν ανέβει ακόμη αρχεία παρακάμψεων.','No response from provider — check the error log for details.'=>'Δεν υπάρχει απάντηση από τον πάροχο — ελέγξτε το αρχείο σφαλμάτων για λεπτομέρειες.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Δεν έχουν διαμορφωθεί δευτερεύουσες γλώσσες. Εγκαταστήστε ένα πακέτο γλώσσας παραπάνω για να ενεργοποιήσετε το πλαίσιο προτύπων.','No source content found to translate.'=>'Δεν βρέθηκε περιεχόμενο πηγής για μετάφραση.','No source page linked yet.'=>'Δεν έχει ακόμη συσχετιστεί σελίδα πηγής.','No template part references needed updating.'=>'Δεν χρειάζεται ενημέρωση αναφορών τμήματος προτύπου.','No {lang} translation registered (TRID missing)'=>'Δεν έχει καταχωρηθεί μετάφραση {lang} (TRID λείπει)','Notes'=>'Σημειώσεις','Notice message'=>'Μήνυμα ειδοποίησης','Notice settings'=>'Ρυθμίσεις ειδοποίησης','Oldest cached block'=>'Παλαιότερο αποθηκευμένο μπλοκ','Oldest cached response'=>'Παλαιότερη αποθηκευμένη απάντηση','Only .mo files are accepted.'=>'Επιτρέπονται μόνο αρχεία .mo.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Προαιρετικό πλαίσιο για τους επεξεργαστές (π.χ. "ASIC = Εξειδικευμένο ολοκληρωμένο κύκλωμα εφαρμογής; διατηρείται στα Αγγλικά σε τεχνικά πλαίσια").','Output'=>'Αποτέλεσμα','Output tokens'=>'Εξαγωγικά tokens','overridden'=>'υπερβαλλόμενο','Override file deleted.'=>'Το αρχείο παρακάμψεων διαγράφηκε.','Override file uploaded successfully.'=>'Το αρχείο παρακάμψεων ανέβηκε με επιτυχία.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Όλες οι άλλες λειτουργίες πάντα χρησιμοποιούν την παγκόσμια προεπιλογή.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Παρακάμπτει την προεπιλογή AI για Μετάφραση και Δημιουργία Περιεχομένου σε αυτήν τη σελίδα. Οι προσαρμοσμένες οδηγίες προτροπής σε όλο τον ιστότοπο (Ρυθμίσεις → Συμπεριφορά) προστίθενται πάντα σε κάθε αίτημα, ανεξάρτητα από αυτήν την επιλογή.','Overview'=>'Επισκόπηση','Page'=>'Σελίδα','Part'=>'Μέρος','Paste a footnote, sentence, or any snippet here…'=>'Επικολλήστε μια υποσημείωση, πρόταση ή οποιοδήποτε απόσπασμα εδώ…','Paste text, or select text in the editor first…'=>'Επικολλήστε κείμενο, ή επιλέξτε κείμενο στον επεξεργαστή πρώτα…','Paste text, or select text on the page first…'=>'Επικολλήστε κείμενο, ή επιλέξτε κείμενο στη σελίδα πρώτα…','Paste your API key…'=>'Επικολλήστε το κλειδί API σας…','Path prefix — example.com/de/'=>'Πρόθεμα διαδρομής — example.com/de/','Pattern'=>'Μοτίβο','Pattern has no content to translate.'=>'Το μοτίβο δεν έχει περιεχόμενο για μετάφραση.','Pattern not found.'=>'Το μοτίβο δεν βρέθηκε.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Το μοτίβο μεταφράστηκε και αποθηκεύτηκε. Αντιγράψτε το περιεχόμενο στη δημοσίευση CPT μέσω του επεξεργαστή μπλοκ ή χρησιμοποιήστε το ως σημείο εκκίνησης για ένα Επαναχρησιμοποιήσιμο Μπλοκ.','Pattern translation failed.'=>'Αποτυχία μετάφρασης μοτίβου.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Cache ανά ανάρτηση για μεταφράσεις AI, μετα-περιγραφές, αποσπάσματα και περιεχόμενο. Πάντα ενεργό — δεν απαιτείται διακόπτης. Οι καταχωρίσεις ακυρώνονται αυτόματα όταν αλλάζει το περιεχόμενο ή ο πάροχος/μοντέλο AI. Χρησιμοποιήστε το κουμπί "↺ Επανάληψη μετάφρασης" στη γραμμή εργαλείων ή κάντε κλικ στο Εκκαθάριση παρακάτω για να αναγκάσετε μια νέα κλήση API.','Permalink rules flushed successfully.'=>'Οι κανόνες permalink εκκαθαρίστηκαν με επιτυχία.','Permission denied.'=>'Άρνηση άδειας πρόσβασης.','Persuasive'=>'Πειστικό','PHP constant'=>'σταθερά PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Καρφιτσώστε όρους που δεν πρέπει να μεταφραστούν ή πρέπει πάντα να αποδίδονται με συγκεκριμένο τρόπο (π.χ. ονόματα εμπορικών σημάτων, ονόματα προϊόντων, ακρωνύμια). Οι περιορισμοί γλωσσάρι εισάγονται σε κάθε αίτημα μετάφρασης AI για όλες τις λειτουργίες: μετάφραση ανάρτησης, μετα-περιγραφή, απόσπασμα και μετάφραση προτύπου FSE.','Plain language'=>'Απλή γλώσσα','Please enter some instructions first…'=>'Παρακαλώ εισάγετε πρώτα κάποιες οδηγίες…','Please enter some text first…'=>'Παρακαλώ εισάγετε κάποιο κείμενο πρώτα…','Post'=>'Ανάρτηση','Post not found.'=>'Η ανάρτηση δεν βρέθηκε.','Post Types'=>'Τύποι Ανάρτησης','Prefilled from excerpt. Edit to override.'=>'Προεπιλεγμένο από απόσπασμα. Επεξεργαστείτε για να το αντικαταστήσετε.','Primary Language'=>'Κύρια γλώσσα','Primary language'=>'Κύρια γλώσσα','Primary language saved.'=>'Αποθηκεύτηκε η κύρια γλώσσα.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Βασική γλώσσα: η γλώσσα στην οποία είναι γραμμένο το υπάρχον περιεχόμενό σας. Όλες οι μεταφράσεις παράγονται από αυτήν τη γλώσσα. Η αλλαγή της δεν μετακινεί ή διαγράφει αναρτήσεις.','Processing…'=>'Επεξεργασία…','Provider'=>'Πάροχος','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Ο πάροχος δεν επέστρεψε κείμενο. Ελέγξτε το αρχείο καταγραφής σφαλμάτων του WordPress για τον λεπτομερή λόγο αποτυχίας.','Quality'=>'Ποιότητα','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (προεπιλογή — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Ποιότητα (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Ποιότητα: χρησιμοποιείται για μετάφραση ανάρτησης και δημιουργία περιεχομένου — υψηλότερη ποιότητα, υψηλότερο κόστος.','Quick Translate'=>'Γρήγορη μετάφραση','Quick Translation'=>'Γρήγορη Μετάφραση','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Η Γρήγορη Μετάφραση χρησιμοποιείται για λειτουργία αποσπάσματος/κομματιού — σύντομες περικοπές μεταφράζονται κατ\' απαίτηση από τη γραμμή εργαλείων, τον επεξεργαστή ή τα αναδυόμενα παράθυρα μπλοκ. Χρησιμοποιεί μια ξεχωριστή, ελαφρύτερη διαμόρφωση από τη μετάφραση σε πλήρη σελίδα για να διατηρεί τις απαντήσεις γρήγορες και οικονομικές.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ενεργοποιεί ξανά το canLockBlocks του Gutenberg. Χρησιμότητα για πρότυπα επιμέλειας που πρέπει να αποτρέπουν τους συνεισφέροντες από τη μετακίνηση ή διαγραφή συγκεκριμένων μπλοκ.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ενεργοποιεί ξανά το supportsTemplateMode. Βασικό για τις ροές εργασίας Full-Site-Editing όπου οι υπεροχές προτύπων σε επίπεδο δημοσίευσης είναι σκόπιμες.','Re-generates and updates the cached result.'=>'Αναδημιουργεί και ενημερώνει το αποθηκευμένο αποτέλεσμα.','Re-scan'=>'Επανασάρωση','Re-scanning…'=>'Επανεξέταση…','Re-translate'=>'Επαναμετάφραση','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ανακατεύθυνση επισκεπτών στη προτιμώμενη γλώσσα τους βάσει της κεφαλίδας Accept-Language του περιηγητή','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Βελτίωση περαιτέρω — π.χ. "κάντε το πιο σύντομο" ή "χρησιμοποιήστε επίσημο τόνο"…','Refine further:'=>'Βελτιώστε περαιτέρω:','Refinement'=>'Βελτίωση','Refinement failed — please try again.'=>'Η βελτίωση απέτυχε — παρακαλώ δοκιμάστε ξανά.','Refining…'=>'Βελτιώνεται…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Αναγεννά τους κανόνες επαναγραφής του WordPress ώστε τα προθέματα URL, τα συγκεκριμένα για τη γλώσσα slug και οι ανακατατάξεις αρχείων να είναι συγχρονισμένα. Απαραίτητο μετά την αλλαγή της κύριας γλώσσας ή την προσθήκη νέας υποστήριξης γλώσσας.','Remove stored key'=>'Αφαίρεση αποθηκευμένου κλειδιού','Report an issue on GitHub'=>'Αναφορά προβλήματος στο GitHub','Request failed — please try again.'=>'Το αίτημα απέτυχε — παρακαλώ δοκιμάστε ξανά.','Request failed.'=>'Το αίτημα απέτυχε.','Request failed. Check your connection.'=>'Το αίτημα απέτυχε. Ελέγξτε τη σύνδεσή σας.','Request failed. Please try again.'=>'Το αίτημα απέτυχε. Παρακαλώ δοκιμάστε ξανά.','Requests'=>'Αιτήματα','Reset'=>'Επαναφορά','Result will appear here…'=>'Το αποτέλεσμα θα εμφανιστεί εδώ…','Retranslate'=>'Επαναμετάφραση','Retranslating…'=>'Επαναμεταφράζοντας…','Review carefully — links and slugs not updated.'=>'Ελέγξτε προσεκτικά — οι σύνδεσμοι και τα slugs δεν ενημερώθηκαν.','Review translation before applying'=>'Ελέγξτε τη μετάφραση πριν την εφαρμόσετε','Revise'=>'Επανεξέταση','Revision'=>'Αναθεώρηση','Revision Type'=>'Τύπος αναθεώρησης','Router'=>'Δρομολογητής','Router Tab'=>'Καρτέλα δρομολογητή','Save Debug Setting'=>'Αποθήκευση ρύθμισης αποσφαλμάτωσης','Save Router Settings'=>'Αποθήκευση Ρυθμίσεων Δρομολογητή','Save Settings'=>'Αποθήκευση ρυθμίσεων','Save the post to persist changes.'=>'Αποθηκεύστε τη δημοσίευση για να διατηρήσετε τις αλλαγές.','Save Uninstall Setting'=>'Αποθήκευση ρύθμισης απεγκατάστασης','Saved to the meta description field when you apply.'=>'Αποθηκεύτηκε στο πεδίο μετα-περιγραφής κατά την εφαρμογή.','Scan failed: '=>'Η σάρωση απέτυχε: ','Scan request failed. Please try again.'=>'Απέτυχε το αίτημα σάρωσης. Παρακαλώ δοκιμάστε ξανά.','Scanning posts for broken language links…'=>'Ανίχνευση αναρτήσεων για σπασμένους συνδέσμους γλώσσας…','Search'=>'Αναζήτηση','Search Results'=>'Αποτελέσματα Αναζήτησης','Security check failed — file path is not permitted.'=>'Απέτυχε ο έλεγχος ασφαλείας — η διαδρομή αρχείου δεν επιτρέπεται.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Επιλέξτε μια γλώσσα για να διαχειριστείτε τα πρότυπα FSE, τα μέρη προτύπων και τα μενού πλοήγησης.','Select language'=>'Επιλογή γλώσσας','SEO character-count info'=>'Πληροφορίες χαρακτήρων SEO','Server setup (subdomain)'=>'Ρύθμιση διακομιστή (υποτομέας)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ορίζει τη προεπιλεγμένη συμπεριφορά AI για όλες τις λειτουργίες σε ολόκληρο τον ιστότοπο. Τα μεμονωμένα δημοσιεύματα μπορούν να το παρακάμψουν για Μετάφραση και Δημιουργία Περιεχομένου μέσω του μετα-κουτιού Lingua Forge.','Settings'=>'Ρυθμίσεις','Settings saved.'=>'Οι ρυθμίσεις αποθηκεύτηκαν.','Show home link'=>'Εμφάνιση συνδέσμου αρχικής','Shown when no translation exists for the visitor\'s language.'=>'Εμφανίζεται όταν δεν υπάρχει μετάφραση για τη γλώσσα του επισκέπτη.','Single'=>'Μοναδικό','Single %s'=>'Μονό %s','Single: %s'=>'Μονό: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Επίπεδο ορίου AI σε όλο τον ιστότοπο ανά UTC ημέρα (μετρά τόσο τις μεταφράσεις Toolbar όσο και τις αναθεωρήσεις μπλοκ). Η καταμέτρηση επαναφέρεται τα μεσάνυχτα UTC. Ορίστε το σε 0 για απενεργοποίηση του ορίου.','Size'=>'Μέγεθος','Some link fixes failed.'=>'Ορισμένες διορθώσεις συνδέσμων απέτυχαν.','Some nav ref fixes failed.'=>'Ορισμένες διορθώσεις αναφορών πλοήγησης απέτυχαν.','Some part fixes failed.'=>'Ορισμένες διορθώσεις μερών απέτυχαν.','Some parts could not be created.'=>'Ορισμένα μέρη δεν μπόρεσαν να δημιουργηθούν.','Some templates could not be created.'=>'Ορισμένα πρότυπα δεν μπόρεσαν να δημιουργηθούν.','Some translations failed.'=>'Ορισμένες μεταφράσεις απέτυχαν.','Source file not found.'=>'Το αρχείο πηγής δεν βρέθηκε.','Source lang'=>'Γλώσσα πηγής','Source language'=>'Γλώσσα πηγής','Source term'=>'Όρος πηγής','Standard'=>'Τυπικό','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Η Standard χρησιμοποιεί τη δική της ρυθμισμένη θερμοκρασία κάθε λειτουργίας: Μετάφραση T=0.2 (ακριβής), Γρήγορη Μετάφραση T=0.4, Δημιουργία Περιεχομένου T=0.6 (δημιουργική). Οι άλλες προεπιλογές εφαρμόζουν μια σταθερή θερμοκρασία σε όλες τις λειτουργίες.','Status'=>'Κατάσταση','Status / Actions'=>'Κατάσταση / Ενέργειες','Storytelling'=>'Αφήγηση','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Λειτουργία αυστηρής διατήρησης για νομικό, κανονιστικό, ιατρικό ή τεχνικό περιεχόμενο. Όταν είναι ενεργό, κάθε λειτουργία AI χρησιμοποιεί χαμηλή θερμοκρασία δειγματοληψίας και προσθέτει το προσάρτημα παρακάτω στην προτροπή του συστήματος — η ορολογία, οι αριθμοί άρθρων, οι μονάδες, τα ονόματα εμπορικών σημάτων και η κανονιστική γλώσσα διατηρούνται αυτούσια και όχι παραφρασμένα.','Structured Outline'=>'Δομημένη περίληψη','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Ο τρόπος υποτομέα απαιτεί από τον διακομιστή σας να δείχνει όλους τους υποτομείς γλώσσας (π.χ. de.example.com) σε αυτήν την εγκατάσταση WordPress. Μετά την αλλαγή τρόπου, καθαρίστε τους κανόνες permalink και διαγράψτε τυχόν cache. Αν η αρχική URL περιλαμβάνει www (π.χ. www.example.com), χρησιμοποιήστε το φίλτρο lf_base_domain για να ορίσετε το απλό ανώτατο domain ώστε οι υποτομείς να κατασκευάζονται σωστά.','Subdomain — de.example.com/'=>'Υποτομέας — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Υποστηριζόμενοι πάροχοι: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Μόνο ένας πάροχος είναι ενεργός κάθε φορά. Επιλέξτε τον ενεργό πάροχο στην καρτέλα Γενικά.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, ανά λειτουργία','Target lang'=>'Γλώσσα στόχου','Target Language'=>'Γλώσσα προορισμού','Target language'=>'Γλώσσα στόχου','Target term'=>'Όρος στόχου','Target: 140–160 chars for optimal SERP display'=>'Στόχος: 140–160 χαρακτήρες για βέλτιστη εμφάνιση στη SERP','Technical'=>'Τεχνικό','Technical / Scientific'=>'Τεχνικό / Επιστημονικό','Technical / Scientific instructions'=>'Τεχνικές / Επιστημονικές οδηγίες','Template "%s" already exists.'=>'Το πρότυπο "%s" υπάρχει ήδη.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Το πρότυπο "{expected}" δεν υπάρχει — δημιουργήστε το πρώτα στον Επεξεργαστή Ιστοσελίδων.','Template has no content.'=>'Το πρότυπο δεν έχει περιεχόμενο.','Template mode'=>'Λειτουργία προτύπου','Template not found or not stored in the database.'=>'Το πρότυπο δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template part "%s" already exists.'=>'Το τμήμα προτύπου "%s" υπάρχει ήδη.','Template part has no content.'=>'Το τμήμα προτύπου δεν έχει περιεχόμενο.','Template part not found or not stored in the database.'=>'Το τμήμα προτύπου δεν βρέθηκε ή δεν αποθηκεύτηκε στη βάση δεδομένων.','Template Parts'=>'Μέρη προτύπων','Templates'=>'Πρότυπα','Test connection'=>'Δοκιμή σύνδεσης','Testing…'=>'Δοκιμή…','Text domain / locale'=>'Τομέας / τοπική ρύθμιση','Text to translate'=>'Κείμενο προς μετάφραση','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Η Cache Απαντήσεων API αποθηκεύει το ακατέργαστο αποτέλεσμα κάθε αίτησης AI — μετάφραση, μετα-περιγραφή, απόσπασμα και δημιουργία περιεχομένου — με κλειδί έναν κατακερματισμό των εισόδων (περιεχόμενο, ζεύγος γλωσσών, πάροχος, μοντέλο). Οι επόμενες αιτήσεις με τα ίδια δεδομένα εξυπηρετούνται από την cache χωρίς κλήση API. Η cache διαφέρει από τη Μνήμη Μετάφρασης: η Μνήμη Μετάφρασης λειτουργεί σε επίπεδο μπλοκ και μοιράζεται μεταξύ αναρτήσεων. Η Cache Απαντήσεων API λειτουργεί σε επίπεδο λειτουργίας και είναι κλειδωμένη ανά ανάρτηση.','The editor did not accept the content — please try again.'=>'Ο επεξεργαστής δεν αποδέχτηκε το περιεχόμενο — παρακαλώ δοκιμάστε ξανά.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Το επίπεδο Light χρησιμοποιεί το γρήγορο μοντέλο που διαμορφώνεται στον πίνακα Μοντέλων παραπάνω (προεπιλογή: Haiku / Flash). Μεταβείτε στην Ποιότητα αν χρειάζεστε την ίδια ακρίβεια μετάφρασης με τη λειτουργία πλήρους σελίδας για αποσπάσματα.','The phrase as it appears in the source text.'=>'Η φράση όπως εμφανίζεται στο πρωτότυπο κείμενο.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Η κύρια γλώσσα σερβίρεται πάντα στην ρίζα του ιστότοπού σας — χωρίς πρόθεμα URL στη διαδρομή σε λειτουργία μονοπατιού, χωρίς υποτομέα γλώσσας σε λειτουργία υποτομέα. Όλες οι άλλες γλώσσες χρησιμοποιούν είτε πρόθεμα διαδρομής /lang/ (π.χ. example.com/de/) είτε υποτομέα γλώσσας (π.χ. de.example.com), ανάλογα με τη ρύθμιση δομής URL παρακάτω.','The source page has no footnotes.'=>'Η σελίδα πηγής δεν έχει υποσημειώσεις.','The upload failed — please try again.'=>'Η μεταφόρτωση απέτυχε — παρακαλώ δοκιμάστε ξανά.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Αυτές οι υποσημειώσεις προέρχονται από τη σελίδα πηγής και εμφανίζονται εδώ μόνο για αναφορά. Προσθέστε τες σε αυτή τη σελίδα χρησιμοποιώντας τον επεξεργαστή μπλοκ.','This is the source page. Footnotes are edited directly in the block editor.'=>'Αυτή είναι η αρχική σελίδα. Οι υποσημειώσεις επεξεργάζονται απευθείας στον επεξεργαστή μπλοκ.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Αυτό το κλειδί παρέχεται αυτήν τη στιγμή από έναν διακομιστή %s και δεν μπορεί να αφαιρεθεί εδώ. Εισάγετε ένα νέο κλειδί παραπάνω για να το αντικαταστήσετε με μια τιμή βάσης δεδομένων.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Συμβουλή: για να επαναφέρετε ένα μοντέλο στην ενσωματωμένη προεπιλογή, διαγράψτε το πεδίο και αποθηκεύστε.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Για να χρησιμοποιήσετε ένα προσαρμοσμένο μυστικό κρυπτογράφησης (αντί της προεπιλεγμένης τιμής wp_salt), προσθέστε το αυτό στο wp-config.php:','Today'=>'Σήμερα','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Η κατανάλωση tokens συγκεντρώνεται ανά λειτουργία, πάροχο και μοντέλο. Καταγράφεται σε κάθε επιτυχημένη κλήση AI. Τα pings Δοκιμής Σύνδεσης εξαιρούνται σκόπιμα ώστε να μην επηρεάζουν τα σύνολα. Ο υποκείμενος πίνακας συγκεντρώνει καθημερινά — επιλέξτε ένα παράθυρο παρακάτω για να το δείτε.','Tone'=>'Τόνος','tone'=>'τόνος','Tone:'=>'Τόνος:','Too many AI requests. Please retry in %d seconds.'=>'Πάρα πολλά αιτήματα AI. Παρακαλώ δοκιμάστε ξανά σε %d δευτερόλεπτα.','Total'=>'Σύνολο','Total tokens'=>'Σύνολο tokens','Translate'=>'Μετάφραση','Translate / Revise'=>'Μετάφραση / Αναθεώρηση','Translate / Revise block'=>'Μεταφραστικό / Αναθεωρητικό μπλοκ','Translate all'=>'Μετάφραση όλων','Translate chunk'=>'Μεταφράστε το τμήμα','Translate Content'=>'Μετάφραση περιεχομένου','Translate missing'=>'Αποτυχία μετάφρασης','Translate page…'=>'Μετάφραση σελίδας…','Translated content'=>'Μεταφρασμένο περιεχόμενο','Translated Names'=>'Μεταφρασμένα ονόματα','Translated title'=>'Μεταφρασμένος τίτλος','Translated to:'=>'Μεταφράστηκε σε:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Μεταφράστηκε. Ανασκόπηση στον Επεξεργαστή Ιστότοπου — οι εσωτερικοί σύνδεσμοι, οι διευθύνσεις URL πλοήγησης και τα ονόματα προτύπων δεν ενημερώνονται αυτόματα.','Translating…'=>'Μεταφράζοντας…','Translation'=>'Μετάφραση','Translation Caching'=>'Αποθήκευση cache μεταφράσεων','Translation found but permalink could not be generated'=>'Βρέθηκε μετάφραση, αλλά ο σύνδεσμος μόνιμης αναφοράς δεν μπόρεσε να δημιουργηθεί','Translation Limits'=>'Όρια Μετάφρασης','Translation Limits & Behavior'=>'Όρια και συμπεριφορά μετάφρασης','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Όρια μετάφρασης: ελέγξτε ποιοι ρόλοι χρηστών μπορούν να ενεργοποιήσουν τη μετάφραση AI και ορίστε έναν μηνιαίο προϋπολογισμό tokens. Η υπέρβαση του προϋπολογισμού διακόπτει τις κλήσεις AI μέχρι την επαναφορά του μήνα.','Translation Memory'=>'Μνήμη Μετάφρασης','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Η μνήμη μεταφράσεων αποθηκεύει τα αποτελέσματα AI με βάση το περιεχόμενο, το ζεύγος γλωσσών, τον πάροχο και το μοντέλο. Η επεξεργασία μιας ανάρτησης ακυρώνει την καταχώριση cache, ώστε η επόμενη κλήση μετάφρασης να λαμβάνει φρέσκο αποτέλεσμα.','Translation Memory cleared. %d cached block was removed.'=>'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.' . "\0" . 'Η μνήμη μετάφρασης διαγράφηκε. %d αποθηκευμένα μπλοκ αφαιρέθηκαν.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Μνήμη Μετάφρασης: αποθηκεύει ολόκληρη την μεταφρασμένη ανάρτηση ανά περιεχόμενο. Διαγράψτε την όταν θέλετε να αναγκάσετε μια επανεπεξεργασία όλων των αναρτήσεων, ανεξάρτητα αν το περιεχόμενό τους άλλαξε.','Translation workflow'=>'Ροή εργασίας μετάφρασης','Translation, Content Generator'=>'Μετάφραση, Δημιουργός Περιεχομένου','Type'=>'Τύπος','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Απεγκατάσταση Συμπεριφοράς','Uninstall setting saved.'=>'Αποθηκεύτηκε η ρύθμιση απεγκατάστασης.','unknown error'=>'άγνωστο σφάλμα','Unknown provider.'=>'Άγνωστος πάροχος.','Up'=>'Πάνω','Upload .mo file'=>'Ανέβασμα αρχείου .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Ανεβάστε συμπιεσμένα αρχεία .mo για να παρακάμψετε τις συμβολοσειρές πρόσθετου τρίτου μέρους για συγκεκριμένες τοπικές ρυθμίσεις — για παράδειγμα, μια προσαρμοσμένη μετάφραση VikBooking που χρησιμοποιεί "διαμέρισμα" αντί για "δωμάτιο". Τα αρχεία πρέπει να ακολουθούν τη συμβατική ονοματοδοσία του WordPress: {textdomain}-{locale}.mo (π.χ. vikbooking-ca.mo). Αποθηκεύονται στον φάκελο ανεβάσματος και επιβιώνουν από ενημερώσεις πρόσθετων.','Upload Override'=>'Ανέβασμα Παρακάμψεων','URL could not be mapped to a post — check the link target exists'=>'Ο σύνδεσμος URL δεν μπόρεσε να αντιστοιχιστεί σε ανάρτηση — ελέγξτε αν υπάρχει ο στόχος του συνδέσμου','URL structure'=>'Δομή URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Δομή URL: λειτουργία προθέματος διαδρομής (example.com/de/) που δεν απαιτεί αλλαγές στον διακομιστή. Λειτουργία υποτομέα (de.example.com) που απαιτεί μια εγγραφή wildcard DNS, ένα πιστοποιητικό SSL wildcard και μια αλλαγή στη διαμόρφωση του διακομιστή — δείτε τον οδηγό ρύθμισης διακομιστή.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Χρησιμοποιήστε τις καρτέλες στην κορυφή αυτής της σελίδας για να διαμορφώσετε κάθε περιοχή. Οι αλλαγές στην καρτέλα δρομολογητή λαμβάνουν άμεσα effect; οι αλλαγές στα κλειδιά AI και τις ρυθμίσεις μοντέλου εφαρμόζονται στην επόμενη αίτηση AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Πίνακας ορολογίας που διαχειρίζεται ο χρήστης ανά ζεύγος γλωσσών. Οι καταχωρίσεις προστίθενται στην προτροπή συστήματος μετάφρασης, ώστε η ΤΝ να χρησιμοποιεί συνεπώς τους προτιμώμενους όρους — κρίσιμο για το λεξιλόγιο τομέα ("kWp", "PPA", "σημείο διασύνδεσης"), ονόματα εμπορικών σημάτων που δεν πρέπει να μεταφράζονται, και τυποποιημένη διατύπωση κανονισμών. Και τα δύο πεδία γλώσσας είναι προαιρετικά: αφήστε το "Πηγή γλώσσα" κενό για να εφαρμοστεί η καταχώριση ανεξάρτητα από τη γλώσσα από την οποία μεταφράζετε· αφήστε το "Στόχος γλώσσα" κενό για να το εφαρμόσετε σε όλες τις στοχευόμενες γλώσσες ταυτόχρονα.','Using custom meta description.'=>'Χρησιμοποιώντας προσαρμοσμένη μετα-περιγραφή.','View'=>'Προβολή','View built-in default'=>'Προβολή ενσωματωμένης προεπιλογής','View details'=>'Προβολή λεπτομερειών','View Lingua Forge details'=>'Προβολή λεπτομερειών Lingua Forge','Visit plugin site'=>'Επισκεφθείτε τον ιστότοπο του πρόσθετου','Warning:'=>'Προειδοποίηση:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Όταν ενεργοποιείται η καταγραφή αποσφαλμάτωσης (μέσω του διακόπτη παρακάτω ή ορίζοντας το LINGUAFORGE_AI_DEBUG στο wp-config.php), οι λειτουργίες μετάφρασης και μετάφρασης προτύπων FSE γράφουν τις ακατέργαστες προτροπές AI και τις απαντήσεις τους στον δίσκο για αποσφαλμάτωση. Χρησιμοποιήστε αυτήν την ενότητα για να παρακολουθείτε αυτήν την έξοδο και να την διαγράψετε μόλις έχετε ό,τι χρειάζεστε — τα αρχεία μπορούν να αυξηθούν γρήγορα σε μεγάλες σελίδες. Διαμορφώστε τον προορισμό καταλόγου μέσω του φίλτρου linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Όταν ενεργοποιηθεί, οι επισκέπτες που επισκέπτονται για πρώτη φορά χωρίς cookie γλώσσας και χωρίς πρόθεμα γλώσσας στη διεύθυνση URL ανακατευθύνονται στην πιο κοντινή αντιστοιχισμένη έκδοση γλώσσας. Η ανακατεύθυνση παραλείπεται αν η προτιμώμενη γλώσσα του περιηγητή δεν είναι ανάμεσα στις ενεργές γλώσσες δρομολόγησης. Μόλις ένας επισκέπτης επιλέξει μια γλώσσα μέσω του διακόπτη, το cookie έχει προτεραιότητα και η κεφαλίδα του περιηγητή αγνοείται σε όλες τις μελλοντικές επισκέψεις.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Ποιο επίπεδο μοντέλου να χρησιμοποιήσετε για μετάφραση ολόκληρης σελίδας. Η ποιότητα χρησιμοποιεί το μοντέλο που έχει διαμορφωθεί στον πίνακα Μοντέλων και προτείνεται για ακριβή, μακροσκελή μετάφραση. Μεταβείτε σε Ελαφρύ μόνο αν η ταχύτητα ή το κόστος είναι προτεραιότητα και το περιεχόμενο είναι σύντομο.','WP-CLI reference'=>'Αναφορά WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Γράψτε προτροπές και απαντήσεις AI στον δίσκο για αποσφαλμάτωση','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Μπορείτε επίσης να ορίσετε κλειδιά ως σταθερές ή μεταβλητές περιβάλλοντος (π.χ. στο wp-config.php). Αυτές οι πηγές χρησιμοποιούνται αυτόματα ως εφεδρική επιλογή όταν δεν αποθηκεύεται κλειδί βάσης δεδομένων.','You do not have permission to manage these settings.'=>'Δεν έχετε άδεια να διαχειριστείτε αυτές τις ρυθμίσεις.','You do not have permission to read this post.'=>'Δεν έχετε άδεια να διαβάσετε αυτήν την ανάρτηση.','{n} stale path(s)'=>'{n} παρωχημένη διαδρομή(ες)','— Any source language —'=>'— Οποιαδήποτε πηγή —','— Any target language —'=>'— Οποιαδήποτε στόχος —','— Any target —'=>'— Οποιαδήποτε στόχος —','— Any —'=>'— Οποιαδήποτε —','— auto-detect —'=>'— αυτόματη ανίχνευση —','— select a language —'=>'— επιλέξτε μια γλώσσα —','— toggle in Settings → Behavior.'=>'— εναλλαγή στις Ρυθμίσεις → Συμπεριφορά.','← Back'=>'← Πίσω','↑ Detected from current post'=>'↑ Ανιχνεύθηκε από την τρέχουσα ανάρτηση','↺ Re-translate'=>'↺ Επαναμετάφραση','↺ Refine'=>'↺ Βελτίωση','↺ Refresh'=>'↺ Ανανεώστε','↺ Refreshing…'=>'↺ Ανανεώνεται…','⚠ Borderline'=>'⚠ Οριακό','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Δεν βρέθηκαν αναρτήσεις <strong>{lang}</strong>. Βεβαιωθείτε ότι όλες οι μεταφρασμένες αναρτήσεις έχουν ορισμένο το μετα-περιεχόμενο Γλώσσα σε <strong>{lang}</strong> στο πλαίσιο μετα-γλώσσας.','⚠ No changes'=>'⚠ Χωρίς αλλαγές','⚠ No changes — re-scan?'=>'⚠ Χωρίς αλλαγές — επανεξέταση;','✅ Fixed ({n})'=>'✅ Διορθώθηκε ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Δεν βρέθηκαν σπασμένοι σύνδεσμοι ή ασυμβατότητες προτύπων για <strong>{lang}</strong>. Σάρωση <strong>{scanned}</strong> ανάρτησης(ων) και σελίδων — όλες οι έλεγχοι πέρασαν. Οι σύνδεσμοι τμημάτων προτύπου (κεφαλίδα, υποσέλιδο, πλαϊνή γραμμή) δεν περιλαμβάνονται εδώ — χρησιμοποιήστε το κουμπί Διόρθωση Τμημάτων Προτύπου για να ελέγξετε αυτά ξεχωριστά.','✅ Template fixed'=>'✅ Το πρότυπο διορθώθηκε','✓ All parts created.'=>'✓ Όλα τα μέρη δημιουργήθηκαν.','✓ All templates created.'=>'✓ Όλα τα πρότυπα δημιουργήθηκαν.','✓ All translated.'=>'✓ Όλες οι μεταφράσεις ολοκληρώθηκαν.','✓ Configured'=>'✓ Διαμορφωμένο','✓ Connection OK'=>'✓ Σύνδεση ΟΚ','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Το περιεχόμενο δημιουργήθηκε — δείτε την επικάλυψη για να ελέγξετε, να βελτιώσετε και να εφαρμόσετε.','✓ Done'=>'✓ Ολοκληρώθηκε','✓ Enabled'=>'✓ Ενεργό','✓ Good length'=>'✓ Καλή διάρκεια','✓ In safe storage'=>'✓ Σε ασφαλή αποθήκευση','✓ Language installed.'=>'✓ Η γλώσσα εγκαταστάθηκε.','✓ Links fixed.'=>'✓ Οι σύνδεσμοι διορθώθηκαν.','✓ Nav refs fixed.'=>'✓ Οι αναφορές πλοήγησης διορθώθηκαν.','✓ Parts fixed.'=>'✓ Τα μέρη διορθώθηκαν.','✓ Pattern translated.'=>'✓ Το μοτίβο μεταφράστηκε.','✓ Refined — review the updated draft above.'=>'✓ Βελτιώθηκε — ελέγξτε το ενημερωμένο προσχέδιο παραπάνω.','✓ Translation saved'=>'✓ Μετάφραση αποθηκευμένη','✗ Disabled'=>'✗ Απενεργό','✗ Error:'=>'✗ Σφάλμα:','✗ Failed:'=>'✗ Απέτυχε:','✗ Not configured'=>'✗ Μη διαμορφωμένο','✗ Too long'=>'✗ Πολύ μεγάλο','✗ Too short'=>'✗ Πολύ σύντομο','❌ Failed'=>'❌ Απέτυχε','📄 Wrong template'=>'📄 Λάθος πρότυπο','📍 Stale path (page moved)'=>'📍 Παλαιά διαδρομή (η σελίδα μετακινήθηκε)']];
